Q["a1-cases-accusative"] = {"version":1,"id":"a1-cases-accusative","topic":"a1-cases-accusative","level":"A1","title":"Stop: accusative","passScore":3,"items":[{"id":"a1-cases-accusative-q1","type":"multiple-choice","kind":"form","prompt":"Lubię ___. (I like music.)","options":["muzyka","muzykę","muzyką","muzyki"],"correct":1,"explanation":"Lubić takes the accusative. Feminine nouns change -a to -ę: muzykę.","optionNotes":["Nominative: the dictionary form, used for the subject.",null,"Instrumental (-ą), used after być and z.","Genitive, used after nie."]},{"id":"a1-cases-accusative-q2","type":"multiple-choice","kind":"form","prompt":"Mam ___. (I have a brother.)","options":["brat","bratem","bratę","brata"],"correct":3,"explanation":"Masculine nouns for people and animals take -a in the accusative: brata.","optionNotes":["Nominative. English does not change the noun here, Polish does.","Instrumental, as in Jestem bratem Anny.","-ę is the feminine ending.",null]},{"id":"a1-cases-accusative-q3","type":"multiple-choice","kind":"form","prompt":"Kupuję ___ telefon. (I'm buying a new phone.)","options":["nowy","nowego","nową","nowe"],"correct":0,"explanation":"Telefon is a masculine thing, so nothing changes: nowy telefon.","optionNotes":[null,"-ego is for masculine people and animals: nowego kolegę.","-ą is the feminine ending.","-e is the neuter ending."]},{"id":"a1-cases-accusative-q4","type":"multiple-choice","kind":"form","prompt":"Which sentence is correct?","options":["Piję dobra kawę.","Piję dobrą kawa.","Piję dobrą kawę.","Piję dobra kawa."],"correct":2,"explanation":"Both words change: the adjective takes -ą and the noun takes -ę.","optionNotes":["The adjective must change too.","The noun must change too.",null,"This is the nominative; the object needs the accusative."]}]};
Q["a1-cases-genitive-basics"] = {"version":1,"id":"a1-cases-genitive-basics","topic":"a1-cases-genitive-basics","level":"A1","title":"Stop: genitive","passScore":3,"items":[{"id":"a1-cases-genitive-basics-q1","type":"multiple-choice","kind":"form","prompt":"Przepraszam, nie mam ___. (Sorry, I don't have time.)","options":["czas","czasu","czasem","czasa"],"correct":1,"explanation":"After nie the object takes the genitive. Czas takes -u: czasu.","optionNotes":["The accusative: after nie the object changes.",null,"The instrumental, used after z meaning \"with\".","Czas takes -u, not -a."]},{"id":"a1-cases-genitive-basics-q2","type":"multiple-choice","kind":"form","prompt":"Nie lubię ___. (I don't like coffee.)","options":["kawę","kawa","kawą","kawy"],"correct":3,"explanation":"Lubię kawę, but after nie: Nie lubię kawy.","optionNotes":["The accusative: correct without nie, but not after nie.","The nominative is not used for an object.","The instrumental, used after z meaning \"with\".",null]},{"id":"a1-cases-genitive-basics-q3","type":"multiple-choice","kind":"meaning","prompt":"Which phrase means \"my sister's room\"?","options":["pokój siostrę","pokój siostry","pokój siostra","pokój siostrą"],"correct":1,"explanation":"The owner comes after the thing, in the genitive: pokój siostry.","optionNotes":["Siostrę is the accusative; the owner takes the genitive.",null,"The owner must be in the genitive.","The instrumental means \"with\"."]},{"id":"a1-cases-genitive-basics-q4","type":"multiple-choice","kind":"form","prompt":"Herbata bez ___, proszę. (Tea without sugar, please.)","options":["cukru","cukier","cukierem","cukiera"],"correct":0,"explanation":"Bez takes the genitive. Cukier loses its e: cukru.","optionNotes":[null,"The nominative: bez needs the genitive.","The instrumental, and the e drops out.","Cukier takes -u, and the e drops out: cukru."]}]};
Q["a1-cases-instrumental-identity"] = {"version":1,"id":"a1-cases-instrumental-identity","topic":"a1-cases-instrumental-identity","level":"A1","title":"Stop: instrumental","passScore":3,"items":[{"id":"a1-cases-instrumental-identity-q1","type":"multiple-choice","kind":"form","prompt":"Jestem ___. (I'm a student. – a man speaking)","options":["student","studentą","studenta","studentem"],"correct":3,"explanation":"A noun after być takes the instrumental: masculine -em.","optionNotes":["The nominative: English does not change the noun, Polish does.","-ą is the feminine ending.","Studenta is another case (accusative).",null]},{"id":"a1-cases-instrumental-identity-q2","type":"multiple-choice","kind":"form","prompt":"Ona jest ___. (She's a teacher.)","options":["nauczycielką","nauczycielka","nauczycielkę","nauczycielem"],"correct":0,"explanation":"Feminine nouns change -a to -ą after być.","optionNotes":[null,"The nominative.","-ę is another case (accusative).","The masculine form; for a woman use nauczycielką."]},{"id":"a1-cases-instrumental-identity-q3","type":"multiple-choice","kind":"form","prompt":"Kawa z ___, proszę. (Coffee with milk, please.)","options":["mleko","mlekiem","mleka","mlekem"],"correct":1,"explanation":"Z meaning 'with' takes the instrumental; after k the ending is -iem: mlekiem.","optionNotes":["The nominative.",null,"Mleka is another case (genitive).","After k the ending is -iem."]},{"id":"a1-cases-instrumental-identity-q4","type":"multiple-choice","kind":"form","prompt":"Which sentence is correct?","options":["To jest studentem.","Jestem zmęczonym.","On jest lekarzem.","Ona jest lekarka."],"correct":2,"explanation":"A noun after być is in the instrumental: lekarzem.","optionNotes":["After to jest the noun stays in the nominative: to jest student.","An adjective alone stays in the nominative: zmęczony.",null,"Lekarka must change: lekarką."]}]};
Q["a1-cases-locative-places"] = {"version":1,"id":"a1-cases-locative-places","topic":"a1-cases-locative-places","level":"A1","title":"Stop: locative","passScore":3,"items":[{"id":"a1-cases-locative-places-q1","type":"multiple-choice","kind":"form","prompt":"Mieszkam w ___. (I live in Kraków.)","options":["Kraków","Krakowa","Krakowie","Krakowem"],"correct":2,"explanation":"After w meaning \"in\" the noun takes the locative: Kraków → w Krakowie.","optionNotes":["The nominative: after w the noun must change.","The genitive, used after do and z: do Krakowa.",null,"The instrumental, used after z meaning \"with\"."]},{"id":"a1-cases-locative-places-q2","type":"multiple-choice","kind":"form","prompt":"Jestem w ___. (I'm at home.)","options":["domie","domu","dom","domem"],"correct":1,"explanation":"Dom is an exception: it takes -u in the locative: w domu.","optionNotes":["Most nouns take -e, but dom takes -u.",null,"The nominative: after w the noun must change.","The instrumental, used after być for jobs and after z."]},{"id":"a1-cases-locative-places-q3","type":"multiple-choice","kind":"form","prompt":"Czekam ___ przystanku. (I'm waiting at the stop.)","options":["w","na","do","z"],"correct":1,"explanation":"Przystanek is one of the na-places: na przystanku, na poczcie, na dworcu.","optionNotes":["Most places take w, but przystanek takes na.",null,"Do means \"to\" and takes the genitive.","Z means \"from\" or \"with\"."]},{"id":"a1-cases-locative-places-q4","type":"multiple-choice","kind":"form","prompt":"Ania mieszka w ___. (Ania lives in Poland.)","options":["Polska","Polski","Polską","Polsce"],"correct":3,"explanation":"Feminine -a → -e in the locative, and k changes to c: Polska → w Polsce.","optionNotes":["The nominative: after w the noun must change.","The genitive, used after z and do: z Polski.","The instrumental.",null]}]};
Q["a1-cases-nominative"] = {"version":1,"id":"a1-cases-nominative","topic":"a1-cases-nominative","level":"A1","title":"Stop: nominative and adjectives","passScore":3,"items":[{"id":"a1-cases-nominative-q1","type":"multiple-choice","kind":"form","prompt":"To jest ___ praca. (This is a new job.)","options":["nowy","nowe","nowa","nowo"],"correct":2,"explanation":"Praca is feminine, so the adjective ends in -a: nowa praca.","optionNotes":["-y is masculine.","-e is neuter.",null,"Nowo is not an adjective form."]},{"id":"a1-cases-nominative-q2","type":"multiple-choice","kind":"form","prompt":"To jest ___ okno. (This is a high window.)","options":["wysoki","wysoka","wysokie","wysoky"],"correct":2,"explanation":"Okno is neuter: -e, and after k it is -ie: wysokie.","optionNotes":["Masculine.","Feminine.",null,"After k write i, never y."]},{"id":"a1-cases-nominative-q3","type":"multiple-choice","kind":"form","prompt":"___ to jest? — To jest lampa.","options":["Kto","Co","Jak","Gdzie"],"correct":1,"explanation":"Co to jest? asks about things.","optionNotes":["Kto is for people and animals.",null,"Jak means 'how'.","Gdzie means 'where'."]},{"id":"a1-cases-nominative-q4","type":"multiple-choice","kind":"form","prompt":"Which is correct? (good coffee)","options":["dobry kawa","dobre kawa","dobrą kawa","dobra kawa"],"correct":3,"explanation":"Kawa is feminine: dobra kawa.","optionNotes":["Masculine adjective with a feminine noun.","Neuter adjective with a feminine noun.","-ą is not the nominative.",null]}]};
Q["a1-functions-asking-to-repeat"] = {"version":1,"id":"a1-functions-asking-to-repeat","topic":"a1-functions-asking-to-repeat","level":"A1","title":"Stop: asking to repeat","passScore":3,"items":[{"id":"a1-functions-asking-to-repeat-q1","type":"multiple-choice","kind":"function","prompt":"You didn't hear what a shop assistant said. What is the most natural thing to say?","options":["Słucham?","Co?","Powtórz!","Nie słucham."],"correct":0,"explanation":"Słucham? (\"I'm listening\") is the polite way to say \"Sorry?\".","optionNotes":[null,"Co? is only for friends; to a stranger it sounds rude.","A command with ty is too blunt for a stranger.","Nie słucham means \"I'm not listening\"."]},{"id":"a1-functions-asking-to-repeat-q2","type":"multiple-choice","kind":"function","prompt":"How do you ask a stranger to speak more slowly?","options":["Mów wolniej!","Proszę mów wolniej.","Proszę mówić wolniej.","Proszę mówić wolny."],"correct":2,"explanation":"Proszę + infinitive: Proszę mówić wolniej.","optionNotes":["A command with ty is too blunt for a stranger.","To a stranger use proszę + infinitive: mówić. (Proszę, mów… is only for friends.)",null,"Wolny is an adjective; \"more slowly\" is wolniej."]},{"id":"a1-functions-asking-to-repeat-q3","type":"multiple-choice","kind":"function","prompt":"You want to know what \"dworzec\" means.","options":["Co jest „dworzec”?","Co znaczy „dworzec”?","Co to mówi „dworzec”?","Jak znaczy „dworzec”?"],"correct":1,"explanation":"\"What does … mean?\" is Co znaczy …?","optionNotes":["A word-for-word copy of \"What is…\"; use znaczy.",null,"Mówić means \"say\", not \"mean\".","With znaczyć the question word is co, not jak."]},{"id":"a1-functions-asking-to-repeat-q4","type":"multiple-choice","kind":"function","prompt":"Do you speak English? (formal, to a man)","options":["Mówi pan w angielsku?","Mówisz po angielsku?","Mówi pan angielski?","Mówi pan po angielsku?"],"correct":3,"explanation":"You speak po angielsku; to a stranger use pan + the \"he\" form.","optionNotes":["The phrase is po angielsku, not w.","Mówisz is informal.","With mówić you need po angielsku.",null]}]};
Q["a1-functions-greetings-introductions"] = {"version":1,"id":"a1-functions-greetings-introductions","topic":"a1-functions-greetings-introductions","level":"A1","title":"Stop: greetings","passScore":3,"items":[{"id":"a1-functions-greetings-introductions-q1","type":"multiple-choice","kind":"function","prompt":"You walk into a small shop in the morning. What do you say?","options":["Cześć!","Dzień dobry!","Dobranoc!","Na razie!"],"correct":1,"explanation":"Dzień dobry is the formal hello for shops, offices and strangers.","optionNotes":["Cześć is only for friends and family.",null,"Dobranoc means good night, when you leave late or go to bed.","Na razie is an informal goodbye."]},{"id":"a1-functions-greetings-introductions-q2","type":"multiple-choice","kind":"function","prompt":"How do you ask a friend how they are?","options":["Jak się masz?","Jak się jesteś?","Jak się pan ma?","Jak masz?"],"correct":0,"explanation":"The informal question is Jak się masz? It uses masz (have), not jesteś (are).","optionNotes":[null,"A calque of English 'how are you'; Polish uses masz here.","This is formal, for a man you don't know well.","się is missing."]},{"id":"a1-functions-greetings-introductions-q3","type":"multiple-choice","kind":"form","prompt":"Mam ___ imię Ewa. (My name is Ewa.)","options":["na","moje","jest","się"],"correct":0,"explanation":"The fixed phrase is Mam na imię … (literally 'I have the name …').","optionNotes":[null,"A calque of 'my name'.","A calque of 'is'.","się belongs to Nazywam się …"]},{"id":"a1-functions-greetings-introductions-q4","type":"multiple-choice","kind":"function","prompt":"At noon you leave a meeting with a new client. What do you say?","options":["Cześć!","Na razie!","Do widzenia!","Dobranoc!"],"correct":2,"explanation":"Do widzenia is the formal goodbye.","optionNotes":["Cześć is informal: friends and family only.","Na razie is informal.",null,"Dobranoc is for late in the evening."]}]};
Q["a1-functions-ordering-shopping"] = {"version":1,"id":"a1-functions-ordering-shopping","topic":"a1-functions-ordering-shopping","level":"A1","title":"Stop: ordering and shopping","passScore":3,"items":[{"id":"a1-functions-ordering-shopping-q1","type":"multiple-choice","kind":"function","prompt":"You order a coffee in a cafe. What is the most natural thing to say?","options":["Chcę kawa.","Poproszę kawę.","Czy mogę mieć kawę?","Poproszę kawa."],"correct":1,"explanation":"Poproszę + the accusative is the polite way to order.","optionNotes":["Chcę sounds blunt, and the object needs -ę.",null,"A word-for-word copy of \"Can I have…?\"","The thing you order takes the accusative: kawę."]},{"id":"a1-functions-ordering-shopping-q2","type":"multiple-choice","kind":"function","prompt":"Can I pay by card?","options":["Czy mogę zapłacić z kartą?","Czy mogę zapłacić karta?","Czy mogę zapłacić kartą?","Czy mogę płacić na kartę?"],"correct":2,"explanation":"\"By card\" is the instrumental alone: kartą.","optionNotes":["No z: the instrumental alone means \"by\".","The nominative: \"by card\" needs kartą.",null,"Na kartę is not how you say \"by card\"."]},{"id":"a1-functions-ordering-shopping-q3","type":"multiple-choice","kind":"form","prompt":"To kosztuje dwadzieścia pięć ___.","options":["złoty","złote","złotych","złotego"],"correct":2,"explanation":"After 25 (a number not ending in 2, 3, 4) say złotych.","optionNotes":["Złoty is for one: jeden złoty.","Złote follows 2, 3, 4 and 22, 23, 24… (but 12, 13, 14 take złotych).",null,"Not used after whole numbers."]},{"id":"a1-functions-ordering-shopping-q4","type":"multiple-choice","kind":"function","prompt":"The waiter asks: Coś jeszcze? You want nothing more. You say:","options":["To wszystko, dziękuję.","Proszę bardzo.","Na wynos.","Co pan poleca?"],"correct":0,"explanation":"Coś jeszcze? means \"Anything else?\". To wszystko means \"That's all\".","optionNotes":[null,"Proszę bardzo is \"Here you are\".","Na wynos is \"to take away\".","Co pan poleca? asks for a recommendation."]}]};
Q["a1-functions-personal-details"] = {"version":1,"id":"a1-functions-personal-details","topic":"a1-functions-personal-details","level":"A1","title":"Stop: personal details","passScore":3,"items":[{"id":"a1-functions-personal-details-q1","type":"multiple-choice","kind":"function","prompt":"How do you ask a man you don't know where he is from?","options":["Skąd jesteś?","Gdzie pan jest?","Skąd pan jesteś?","Skąd pan jest?"],"correct":3,"explanation":"To a stranger use pan + the he form: Skąd pan jest?","optionNotes":["Informal: for friends.","Gdzie pan jest? means 'Where are you (now)?'","Pan takes jest, not jesteś.",null]},{"id":"a1-functions-personal-details-q2","type":"multiple-choice","kind":"function","prompt":"I'm 30.","options":["Jestem trzydzieści lat.","Mam trzydzieści lat.","Mam trzydzieści lata.","Jestem trzydzieści."],"correct":1,"explanation":"Age uses mieć: Mam … lat.","optionNotes":["Age uses mieć, not być.",null,"After 30 say lat; lata is for numbers ending in 2, 3, 4.","Age uses mieć, and lat is missing."]},{"id":"a1-functions-personal-details-q3","type":"multiple-choice","kind":"form","prompt":"Mieszkam w ___. (I live in Kraków.)","options":["Krakowie","Kraków","Krakowa","Krakowem"],"correct":0,"explanation":"After w (in) the city changes: w Krakowie.","optionNotes":[null,"The dictionary form does not follow w.","Krakowa follows z (from): z Krakowa.","Krakowem is the instrumental."]},{"id":"a1-functions-personal-details-q4","type":"multiple-choice","kind":"form","prompt":"Mam dwadzieścia trzy ___. (I'm 23.)","options":["lat","lata","rok","roku"],"correct":1,"explanation":"After numbers ending in 2, 3, 4 (not 12–14) say lata.","optionNotes":["Lat follows the other numbers: dwadzieścia pięć lat.",null,"Rok is one year.","Roku is another form of rok."]}]};
Q["a1-functions-time-dates"] = {"version":1,"id":"a1-functions-time-dates","topic":"a1-functions-time-dates","level":"A1","title":"Stop: time and when","passScore":3,"items":[{"id":"a1-functions-time-dates-q1","type":"multiple-choice","kind":"form","prompt":"Która godzina? — Jest ___. (8:00)","options":["osiem","ósma","ósmej","ósmy"],"correct":1,"explanation":"Hours use the feminine \"eighth\": Jest ósma.","optionNotes":["Hours do not use the plain number.",null,"Ósmej follows o: o ósmej.","The masculine form; godzina is feminine."]},{"id":"a1-functions-time-dates-q2","type":"multiple-choice","kind":"form","prompt":"Film jest o ___. (at seven)","options":["siódma","siedem","siódmej","siódmą"],"correct":2,"explanation":"After o (at) the hour ends in -ej: o siódmej.","optionNotes":["After o the ending changes to -ej.","Hours do not use the plain number.",null,"The -ą ending is not used after o."]},{"id":"a1-functions-time-dates-q3","type":"multiple-choice","kind":"meaning","prompt":"Jest wpół do dziewiątej. What time is it?","options":["9:30","8:30","9:00","8:00"],"correct":1,"explanation":"Wpół do dziewiątej is \"half to nine\": 8:30.","optionNotes":["Polish counts half an hour to the next hour: 9:30 is wpół do dziesiątej.",null,"9:00 is dziewiąta.","8:00 is ósma."]},{"id":"a1-functions-time-dates-q4","type":"multiple-choice","kind":"meaning","prompt":"How do you say \"in the evening\"?","options":["w wieczór","wieczorem","w wieczorze","na wieczór"],"correct":1,"explanation":"\"In the evening\" is one word: wieczorem.","optionNotes":["A word-for-word copy of the English.",null,"Not used for \"in the evening\".","Na wieczór means \"for the evening\"."]}]};
Q["a1-grammar-alphabet-pronunciation"] = {"version":1,"id":"a1-grammar-alphabet-pronunciation","topic":"a1-grammar-alphabet-pronunciation","level":"A1","title":"Stop: alphabet and stress","passScore":3,"items":[{"id":"a1-grammar-alphabet-pronunciation-q1","type":"multiple-choice","kind":"form","prompt":"Warszawa = war-sza-wa. Which syllable is stressed?","options":["war","sza","wa"],"correct":1,"explanation":"Polish stresses the second-to-last syllable: war-SZA-wa.","optionNotes":["English habit: stress on the first syllable.",null,"The last syllable is not stressed in Polish words like this."]},{"id":"a1-grammar-alphabet-pronunciation-q2","type":"multiple-choice","kind":"form","prompt":"Which spelling makes the same sound as ż?","options":["rz","sz","cz","z"],"correct":0,"explanation":"rz and ż are two spellings of one sound, like the s in pleasure.","optionNotes":[null,"sz is the sh in shop.","cz is the ch in church.","z is the z in zoo."]},{"id":"a1-grammar-alphabet-pronunciation-q3","type":"multiple-choice","kind":"form","prompt":"Which letter sounds like the w in English water?","options":["w","ł","u","l"],"correct":1,"explanation":"ł sounds like English w. Polish w sounds like v.","optionNotes":["Polish w sounds like v, as in van.",null,"u is a vowel, like the oo in book.","l is a clear l, as in leaf."]},{"id":"a1-grammar-alphabet-pronunciation-q4","type":"multiple-choice","kind":"form","prompt":"Which spelling is correct? (Thank you.)","options":["Dziekuje.","Dziękuje.","Dziekuję.","Dziękuję."],"correct":3,"explanation":"Both e's in dziękuję have the mark: dzię-ku-ję. The marks are part of the spelling.","optionNotes":["Both marks are missing.","The final ę is missing its mark.","The first ę is missing its mark.",null]}]};
Q["a1-grammar-gender-of-nouns"] = {"version":1,"id":"a1-grammar-gender-of-nouns","topic":"a1-grammar-gender-of-nouns","level":"A1","title":"Stop: gender of nouns","passScore":3,"items":[{"id":"a1-grammar-gender-of-nouns-q1","type":"multiple-choice","kind":"form","prompt":"Which noun is feminine?","options":["dom","noc","okno","tata"],"correct":1,"explanation":"Noc is feminine although it ends in a consonant: ta noc.","optionNotes":["A consonant ending: masculine, ten dom.",null,"-o: neuter, to okno.","A man's word in -a is masculine: ten tata."]},{"id":"a1-grammar-gender-of-nouns-q2","type":"multiple-choice","kind":"form","prompt":"___ okno (this window)","options":["ten","ta","to"],"correct":2,"explanation":"Okno ends in -o, so it is neuter: to okno.","optionNotes":["Ten is masculine.","Ta is feminine.",null]},{"id":"a1-grammar-gender-of-nouns-q3","type":"multiple-choice","kind":"form","prompt":"___ kolega (this friend)","options":["ten","ta","to"],"correct":0,"explanation":"Kolega is a man, so it is masculine although it ends in -a: ten kolega.","optionNotes":[null,"The -a ending misleads: kolega is a man.","To is neuter."]},{"id":"a1-grammar-gender-of-nouns-q4","type":"multiple-choice","kind":"form","prompt":"Gdzie jest telefon? — ___ jest tu.","options":["Ono","On","Ona","One"],"correct":1,"explanation":"Telefon is masculine, so 'it' is on.","optionNotes":["Ono is only for neuter nouns, not for every thing.",null,"Ona is for feminine nouns.","One is plural."]}]};
Q["a1-grammar-possessives-demonstratives"] = {"version":1,"id":"a1-grammar-possessives-demonstratives","topic":"a1-grammar-possessives-demonstratives","level":"A1","title":"Stop: my, your, this","passScore":3,"items":[{"id":"a1-grammar-possessives-demonstratives-q1","type":"multiple-choice","kind":"form","prompt":"To jest ___ siostra. (This is my sister.)","options":["mój","moja","moje","mojego"],"correct":1,"explanation":"Mój agrees with the noun: siostra is feminine, so moja.","optionNotes":["Mój is for masculine nouns.",null,"Moje is for neuter nouns and the plural.","Mojego is the accusative for male people."]},{"id":"a1-grammar-possessives-demonstratives-q2","type":"multiple-choice","kind":"form","prompt":"Ola and her brother.","options":["Ola i jego brat.","Ola i ona brat.","Ola i jej brata.","Ola i jej brat."],"correct":3,"explanation":"Jej (her) depends on the owner, Ola, and never changes.","optionNotes":["Jego means \"his\".","Ona means \"she\", not \"her\".","There is no verb here, so brat stays in the nominative.",null]},{"id":"a1-grammar-possessives-demonstratives-q3","type":"multiple-choice","kind":"form","prompt":"Znasz ___? (Do you know my brother?)","options":["mojego brata","mój brat","moja brata","mojego brat"],"correct":0,"explanation":"Znać takes the accusative. A male person: mojego brata.","optionNotes":[null,"The nominative: the object must change.","Moja is feminine; brat is masculine.","The noun must change too: brata."]},{"id":"a1-grammar-possessives-demonstratives-q4","type":"multiple-choice","kind":"function","prompt":"You ask a woman you don't know: \"Excuse me, is this your bag?\"","options":["Przepraszam, czy to twoja torba?","Przepraszam, czy to pani torbę?","Przepraszam, czy to pani torba?","Przepraszam, czy to panią torba?"],"correct":2,"explanation":"Formal \"your\" for a woman is pani, and it never changes.","optionNotes":["Twoja is for friends and family.","After to the noun stays in the nominative: torba.",null,"Panią is the accusative of pani, not \"your\"."]}]};
Q["a1-grammar-pronouns-pan-pani"] = {"version":1,"id":"a1-grammar-pronouns-pan-pani","topic":"a1-grammar-pronouns-pan-pani","level":"A1","title":"Stop: pronouns and pan / pani","passScore":3,"items":[{"id":"a1-grammar-pronouns-pan-pani-q1","type":"multiple-choice","kind":"form","prompt":"Anna i Ewa? ___ są tu.","options":["Oni","One","Ono","Wy"],"correct":1,"explanation":"A group of women is one. Oni needs at least one man.","optionNotes":["Oni is for a group with at least one man.",null,"Ono is 'it', for neuter nouns.","Wy is 'you', not 'they'."]},{"id":"a1-grammar-pronouns-pan-pani-q2","type":"multiple-choice","kind":"function","prompt":"To an older man you don't know: How are you?","options":["Jak się masz?","Jak się pan ma?","Jak się pan masz?","Jak się macie?"],"correct":1,"explanation":"With strangers use pan (to a man) and the he form of the verb: ma.","optionNotes":["Informal: too familiar for a stranger.",null,"Pan takes the he form ma, not the you form masz.","Wy is never the polite form for one person."]},{"id":"a1-grammar-pronouns-pan-pani-q3","type":"multiple-choice","kind":"form","prompt":"Which pronoun replaces dziecko (a child)?","options":["on","ona","ono","one"],"correct":2,"explanation":"Dziecko is a neuter noun, so the pronoun is ono.","optionNotes":["On is for masculine nouns.","Ona is for feminine nouns.",null,"One is a plural pronoun."]},{"id":"a1-grammar-pronouns-pan-pani-q4","type":"multiple-choice","kind":"form","prompt":"Marek i Ola? ___ są tam.","options":["One","Oni","On","Ona"],"correct":1,"explanation":"The group has a man (Marek), so the pronoun is oni.","optionNotes":["One is only for groups with no men.",null,"On is one man; this is two people.","Ona is one woman; this is two people."]}]};
Q["a1-grammar-questions-negation"] = {"version":1,"id":"a1-grammar-questions-negation","topic":"a1-grammar-questions-negation","level":"A1","title":"Stop: questions and negation","passScore":3,"items":[{"id":"a1-grammar-questions-negation-q1","type":"multiple-choice","kind":"form","prompt":"How do you say \"I don't understand\"?","options":["Rozumiem nie.","Nie rozumiem.","Ja nie rozumiem nie.","Nie robię rozumiem."],"correct":1,"explanation":"Nie goes directly before the verb. There is no helper verb like \"do\".","optionNotes":["Nie goes before the verb, not after it.",null,"One nie before the verb is enough.","Polish has no helper verb: robić means \"do, make\"."]},{"id":"a1-grammar-questions-negation-q2","type":"multiple-choice","kind":"form","prompt":"Nikt ___ wie.","options":["nie","nic","już","też"],"correct":0,"explanation":"Nikt (nobody) needs nie with the verb: Nikt nie wie.","optionNotes":[null,"Nic means \"nothing\", and the verb still needs nie.","Już means \"already\"; the verb needs nie.","Też means \"too\"; the verb needs nie."]},{"id":"a1-grammar-questions-negation-q3","type":"multiple-choice","kind":"function","prompt":"You want to know where someone is from. You ask:","options":["Gdzie jesteś?","Skąd jesteś?","Gdzie jesteś z?","Kiedy jesteś?"],"correct":1,"explanation":"\"Where … from\" is one word: skąd.","optionNotes":["Gdzie jesteś? means \"Where are you (now)?\"",null,"Polish does not put the preposition at the end: use skąd.","Kiedy means \"when\"."]},{"id":"a1-grammar-questions-negation-q4","type":"multiple-choice","kind":"function","prompt":"Czy mówisz po angielsku? — No, I don't.","options":["Nie, mówię.","Nie, nie mówię.","Tak, nie mówię.","Nie mówię nie."],"correct":1,"explanation":"The first nie means \"no\", the second makes the verb negative.","optionNotes":["This means \"No, I do speak\": the verb needs its own nie.",null,"Tak means \"yes\".","Nie goes before the verb, not after it."]}]};
Q["a1-verbs-byc"] = {"version":1,"id":"a1-verbs-byc","topic":"a1-verbs-byc","level":"A1","title":"Stop: być","passScore":3,"items":[{"id":"a1-verbs-byc-q1","type":"multiple-choice","kind":"form","prompt":"My ___ tu. (We're here.)","options":["jesteśmy","jesteście","są","jest"],"correct":0,"explanation":"my → jesteśmy.","optionNotes":[null,"Jesteście goes with wy (you, plural).","Są goes with oni / one (they).","Jest is the he / she / it form."]},{"id":"a1-verbs-byc-q2","type":"multiple-choice","kind":"form","prompt":"Oni ___ tam. (They're over there.)","options":["jest","są","jesteście","jestem"],"correct":1,"explanation":"oni → są.","optionNotes":["Jest is singular: he / she / it is.",null,"Jesteście goes with wy.","Jestem is I am."]},{"id":"a1-verbs-byc-q3","type":"multiple-choice","kind":"form","prompt":"___ moje dzieci. (These are my children.)","options":["To jest","To są","Ten jest","To jesteś"],"correct":1,"explanation":"Dzieci is plural, so to są. To itself never changes.","optionNotes":["To jest is for one person or thing.",null,"Polish says to, not ten, when pointing: to jest, to są.","Jesteś is the you form."]},{"id":"a1-verbs-byc-q4","type":"multiple-choice","kind":"form","prompt":"Pani ___ bardzo miła. (You're very nice. – to a woman)","options":["jesteś","jest","jesteście","są"],"correct":1,"explanation":"Pani takes the she form of the verb: pani jest.","optionNotes":["Jesteś is the ty form; pani uses the she form.",null,"Wy is never the polite form for one person.","Są is plural."]}]};
Q["a1-verbs-common-irregular"] = {"version":1,"id":"a1-verbs-common-irregular","topic":"a1-verbs-common-irregular","level":"A1","title":"Stop: irregular verbs","passScore":3,"items":[{"id":"a1-verbs-common-irregular-q1","type":"multiple-choice","kind":"form","prompt":"Oni ___ obiad. (They are eating lunch.)","options":["jadą","jedzą","jedą","jemy"],"correct":1,"explanation":"Jeść: oni jedzą.","optionNotes":["Jadą is from jechać: \"they are going\".",null,"There is no such form.","Jemy is the my form."]},{"id":"a1-verbs-common-irregular-q2","type":"multiple-choice","kind":"form","prompt":"Ty ___ do Gdańska? (Are you going to Gdańsk by train?)","options":["jadziesz","idziesz","jedziesz","jedzie"],"correct":2,"explanation":"By train you use jechać; the ty form is jedziesz (the stem changes from jad- to jedzi-).","optionNotes":["The stem changes: jadę but jedziesz.","Iść is only on foot.",null,"Jedzie is the on / ona form."]},{"id":"a1-verbs-common-irregular-q3","type":"multiple-choice","kind":"meaning","prompt":"Which sentence means \"I know Kraków\"?","options":["Wiem Kraków.","Znam Kraków.","Mam Kraków.","Wie Kraków."],"correct":1,"explanation":"Places and people take znać; wiedzieć is for facts.","optionNotes":["Wiedzieć is for facts, not places.",null,"Mieć means \"have\".","Wiedzieć is for facts, and wie is the on / ona form."]},{"id":"a1-verbs-common-irregular-q4","type":"multiple-choice","kind":"form","prompt":"Przepraszam, nie ___ dzisiaj. (Sorry, I can't today.)","options":["może","mogę","możę","mogą"],"correct":1,"explanation":"Móc: ja mogę, ty możesz. The ja form keeps g.","optionNotes":["Może is the on / ona form (and also \"maybe\").",null,"The ja form keeps g: mogę.","Mogą is the oni form."]}]};
Q["a1-verbs-going-isc-jechac"] = {"version":1,"id":"a1-verbs-going-isc-jechac","topic":"a1-verbs-going-isc-jechac","level":"A1","title":"Stop: iść and jechać","passScore":3,"items":[{"id":"a1-verbs-going-isc-jechac-q1","type":"multiple-choice","kind":"form","prompt":"Jutro ___ do Gdańska pociągiem. (Tomorrow I'm going to Gdańsk by train.)","options":["idę","jadę","jedziesz","iść"],"correct":1,"explanation":"By train, bus or car the verb is jechać: jadę.","optionNotes":["Iść is only on foot.",null,"Jedziesz is the ty form; the sentence is about \"I\".","The infinitive cannot be the main verb here."]},{"id":"a1-verbs-going-isc-jechac-q2","type":"multiple-choice","kind":"form","prompt":"Idę do ___. (I'm going to the shop.)","options":["sklep","sklepie","sklepu","sklepem"],"correct":2,"explanation":"Do takes the genitive: sklep → do sklepu.","optionNotes":["The nominative: after do the noun must change.","The locative, for where you are: w sklepie.",null,"The instrumental."]},{"id":"a1-verbs-going-isc-jechac-q3","type":"multiple-choice","kind":"form","prompt":"Which sentence means \"I'm going to a concert\"?","options":["Idę do koncertu.","Idę na koncert.","Idę na koncercie.","Idę w koncert."],"correct":1,"explanation":"Events take na + accusative for \"where to\": na koncert.","optionNotes":["Events take na, not do.",null,"Na koncercie (locative) is where you are, not where you are going.","W is not used with koncert."]},{"id":"a1-verbs-going-isc-jechac-q4","type":"multiple-choice","kind":"form","prompt":"Jadę do pracy ___. (I'm going to work by bus.)","options":["autobusem","z autobusem","w autobus","na autobusie"],"correct":0,"explanation":"\"By bus\" is the plain form autobusem, with no preposition.","optionNotes":[null,"Z autobusem means \"together with a bus\".","Not used for \"by bus\"; w autobusie means \"in the bus\".","Na autobusie would mean \"on top of the bus\"."]}]};
Q["a1-verbs-modal-verbs-basics"] = {"version":1,"id":"a1-verbs-modal-verbs-basics","topic":"a1-verbs-modal-verbs-basics","level":"A1","title":"Stop: like, want, can, must","passScore":3,"items":[{"id":"a1-verbs-modal-verbs-basics-q1","type":"multiple-choice","kind":"form","prompt":"Lubię ___. (I like reading.)","options":["czytam","czytać","czytamy","czyta"],"correct":1,"explanation":"After lubię the second verb is the infinitive: czytać.","optionNotes":["Only the first verb takes a person ending.",null,"Czytamy is the my form; only the first verb takes a person ending.","Czyta is the on / ona form."]},{"id":"a1-verbs-modal-verbs-basics-q2","type":"multiple-choice","kind":"meaning","prompt":"\"I can swim\" (I know how). Which verb?","options":["Mogę pływać.","Znam pływać.","Umiem pływać.","Wiem pływać."],"correct":2,"explanation":"Skills you have learnt take umieć.","optionNotes":["Mogę means it is possible or allowed now.","Znać is for people and places.",null,"Wiedzieć is for facts."]},{"id":"a1-verbs-modal-verbs-basics-q3","type":"multiple-choice","kind":"form","prompt":"Ja ___ iść. (I have to go.)","options":["musę","muszę","musi","muszą"],"correct":1,"explanation":"Musieć: s changes to sz in muszę and muszą.","optionNotes":["The s changes to sz: muszę.",null,"Musi is the on / ona form.","Muszą is the oni form."]},{"id":"a1-verbs-modal-verbs-basics-q4","type":"multiple-choice","kind":"meaning","prompt":"What does Nie musisz czekać mean?","options":["You mustn't wait.","You can't wait.","You don't have to wait.","You don't want to wait."],"correct":2,"explanation":"Nie musieć means \"not have to\". \"Mustn't\" is nie wolno.","optionNotes":["\"You mustn't\" is Nie wolno czekać.","\"You can't\" is Nie możesz.",null,"\"You don't want\" is Nie chcesz."]}]};
Q["a1-verbs-past-tense-basics"] = {"version":1,"id":"a1-verbs-past-tense-basics","topic":"a1-verbs-past-tense-basics","level":"A1","title":"Stop: past tense","passScore":3,"items":[{"id":"a1-verbs-past-tense-basics-q1","type":"multiple-choice","kind":"form","prompt":"(a woman speaking) Wczoraj ___ w kinie.","options":["byłem","byłam","była","jestem"],"correct":1,"explanation":"A woman says byłam (I was); a man says byłem.","optionNotes":["A man's form.",null,"Była is \"she was\", not \"I was\".","Present tense; wczoraj needs the past."]},{"id":"a1-verbs-past-tense-basics-q2","type":"multiple-choice","kind":"form","prompt":"Gdzie ___ wczoraj, Tomek? (Where were you yesterday, Tomek?)","options":["byłeś","byłaś","byłem","jesteś"],"correct":0,"explanation":"Talking to a man with ty: byłeś.","optionNotes":[null,"Byłaś is for a woman.","Byłem means \"I was\".","Present tense; wczoraj needs the past."]},{"id":"a1-verbs-past-tense-basics-q3","type":"multiple-choice","kind":"form","prompt":"Pan Adam ___ w banku. (Mr Adam worked in a bank.)","options":["pracował","pracowała","pracujał","pracowałem"],"correct":0,"explanation":"He form: -ł. Verbs in -ować build the past from the infinitive: pracowa-ł.","optionNotes":[null,"Pracowała is for a woman.","The past comes from the infinitive (pracowa-), not the present (pracuj-).","Pracowałem means \"I worked\"."]},{"id":"a1-verbs-past-tense-basics-q4","type":"multiple-choice","kind":"form","prompt":"Kasia says: \"I had a cat.\"","options":["Miałam kota.","Miełam kota.","Miałem kota.","Miała kota."],"correct":0,"explanation":"Mieć: e changes to a in the past. A woman says miałam.","optionNotes":[null,"In -eć verbs the e becomes a: miałam.","Miałem is a man's form.","Miała means \"she had\"."]}]};
Q["a1-verbs-present-conjugations"] = {"version":1,"id":"a1-verbs-present-conjugations","topic":"a1-verbs-present-conjugations","level":"A1","title":"Stop: present tense","passScore":3,"items":[{"id":"a1-verbs-present-conjugations-q1","type":"multiple-choice","kind":"form","prompt":"Ona ___ w banku. (She works in a bank.)","options":["pracuje","pracuję","pracowa","pracują"],"correct":0,"explanation":"Verbs in -ować change to -uj-; the on / ona form ends in -e: pracuje.","optionNotes":[null,"Pracuję is the ja form.","-ować verbs change to -uj-: there is no pracowa.","Pracują is the oni form."]},{"id":"a1-verbs-present-conjugations-q2","type":"multiple-choice","kind":"form","prompt":"My ___ w Krakowie. (We live in Kraków.)","options":["mieszkam","mieszkają","mieszkamy","mieszkacie"],"correct":2,"explanation":"The my form ends in -my: mieszkamy.","optionNotes":["Mieszkam is the ja form.","Mieszkają is the oni form.",null,"Mieszkacie is the wy form."]},{"id":"a1-verbs-present-conjugations-q3","type":"multiple-choice","kind":"form","prompt":"How do you say \"I'm reading\"?","options":["Jestem czytam.","Czytam.","Jestem czytać.","Czytać."],"correct":1,"explanation":"Polish has one present tense: czytam is both \"I read\" and \"I'm reading\".","optionNotes":["Never add być to a verb in the present.",null,"Być + infinitive is not a tense.","Czytać is the infinitive, \"to read\"."]},{"id":"a1-verbs-present-conjugations-q4","type":"multiple-choice","kind":"form","prompt":"Ty ___ po polsku? (Do you speak Polish?)","options":["mówisz","mówię","mówi","mówysz"],"correct":0,"explanation":"Mówić follows the -ę, -isz pattern: ty mówisz.","optionNotes":[null,"Mówię is the ja form.","Mówi is the on / ona form.","Mówić is an -ić verb, so it keeps i: mówisz. -ysz comes only after cz, sz, rz, ż."]}]};
Q["a1-vocabulary-family-people"] = {"version":1,"id":"a1-vocabulary-family-people","topic":"a1-vocabulary-family-people","level":"A1","title":"Stop: family and people","passScore":3,"items":[{"id":"a1-vocabulary-family-people-q1","type":"multiple-choice","kind":"form","prompt":"___ brat (my brother)","options":["mój","moja","moje"],"correct":0,"explanation":"Brat is masculine: mój brat.","optionNotes":[null,"Moja is feminine.","Moje is neuter."]},{"id":"a1-vocabulary-family-people-q2","type":"multiple-choice","kind":"form","prompt":"What is the female form of lekarz (doctor)?","options":["lekarza","lekarka","lekarzka","lekarkę"],"correct":1,"explanation":"lekarz → lekarka.","optionNotes":["Lekarza is another case of lekarz.",null,"Not a word: rz drops before -ka: lekarz → lekarka.","Lekarkę is another case of lekarka."]},{"id":"a1-vocabulary-family-people-q3","type":"multiple-choice","kind":"form","prompt":"I'm Polish. (a woman speaking)","options":["Jestem polska.","Jestem Polakiem.","Jestem Polka.","Jestem Polką."],"correct":3,"explanation":"Use the nationality noun in the instrumental, with a capital letter: Polką.","optionNotes":["Polska is an adjective (and the name of the country); use the noun.","Polakiem is the man's form.","After jestem the noun changes: -a → -ą.",null]},{"id":"a1-vocabulary-family-people-q4","type":"multiple-choice","kind":"form","prompt":"Which word means 'parents'?","options":["krewni","rodzina","rodzice","dziadkowie"],"correct":2,"explanation":"Rodzice means parents.","optionNotes":["Krewni means relatives.","Rodzina means family.",null,"Dziadkowie means grandparents."]}]};
Q["a1-vocabulary-food-drink"] = {"version":1,"id":"a1-vocabulary-food-drink","topic":"a1-vocabulary-food-drink","level":"A1","title":"Stop: food and drink","passScore":3,"items":[{"id":"a1-vocabulary-food-drink-q1","type":"multiple-choice","kind":"meaning","prompt":"What is obiad?","options":["breakfast","the main meal of the day","dessert","a drink"],"correct":1,"explanation":"Obiad is the main hot meal, often eaten in the afternoon.","optionNotes":["Breakfast is śniadanie.",null,"Dessert is deser.","Obiad is a meal, not a drink."]},{"id":"a1-vocabulary-food-drink-q2","type":"multiple-choice","kind":"form","prompt":"Poproszę ___ z cytryną. (A tea with lemon, please.)","options":["herbata","herbatę","jedna herbata","herbatą"],"correct":1,"explanation":"After poproszę the feminine -a becomes -ę: herbatę.","optionNotes":["The dictionary form: after poproszę the noun changes.",null,"Polish has no \"a\"; jedna means \"one\".","-ą is the instrumental, used after z."]},{"id":"a1-vocabulary-food-drink-q3","type":"multiple-choice","kind":"form","prompt":"Lody ___ zimne.","options":["są","jest","jesteś","jestem"],"correct":0,"explanation":"Lody (ice cream) is plural in Polish, so it takes są.","optionNotes":[null,"Lody is plural: są, not jest.","Jesteś is the ty form.","Jestem is the ja form."]},{"id":"a1-vocabulary-food-drink-q4","type":"multiple-choice","kind":"meaning","prompt":"Which word is a vegetable?","options":["jabłko","truskawki","ciasto","ogórek"],"correct":3,"explanation":"Ogórek is a cucumber.","optionNotes":["Jabłko is an apple: a fruit.","Truskawki are strawberries: a fruit.","Ciasto is cake.",null]}]};
Q["a1-vocabulary-home-city"] = {"version":1,"id":"a1-vocabulary-home-city","topic":"a1-vocabulary-home-city","level":"A1","title":"Stop: home and town","passScore":3,"items":[{"id":"a1-vocabulary-home-city-q1","type":"multiple-choice","kind":"meaning","prompt":"Where do you buy medicine?","options":["w aptece","na poczcie","w kinie","na dworcu"],"correct":0,"explanation":"Apteka is a pharmacy.","optionNotes":[null,"Poczta is the post office.","Kino is the cinema.","Dworzec is a station."]},{"id":"a1-vocabulary-home-city-q2","type":"multiple-choice","kind":"meaning","prompt":"Where do you wait for a tram in the street?","options":["na dworcu","na lotnisku","na przystanku","w windzie"],"correct":2,"explanation":"Przystanek is a bus or tram stop.","optionNotes":["Dworzec is a station building.","Lotnisko is an airport.",null,"Winda is a lift."]},{"id":"a1-vocabulary-home-city-q3","type":"multiple-choice","kind":"form","prompt":"Drzwi ___ otwarte. (The door is open.)","options":["jest","są","jesteś","jestem"],"correct":1,"explanation":"Drzwi (door) is plural only, so it takes są.","optionNotes":["Drzwi is plural: są, not jest.",null,"Jesteś is the ty form.","Jestem is the ja form."]},{"id":"a1-vocabulary-home-city-q4","type":"multiple-choice","kind":"form","prompt":"Mam ___ mieszkanie.","options":["duży","duża","duże","dużego"],"correct":2,"explanation":"Mieszkanie is neuter, so the adjective ends in -e.","optionNotes":["The masculine form.","The feminine form.",null,"-ego is for masculine people and animals in the accusative."]}]};
Q["a1-vocabulary-numbers-days-months"] = {"version":1,"id":"a1-vocabulary-numbers-days-months","topic":"a1-vocabulary-numbers-days-months","level":"A1","title":"Stop: numbers, days, months","passScore":3,"items":[{"id":"a1-vocabulary-numbers-days-months-q1","type":"multiple-choice","kind":"form","prompt":"15 = ?","options":["pięćnaście","piętnaście","piętnascie","pięćdziesiąt"],"correct":1,"explanation":"Fifteen is spelled with t: piętnaście.","optionNotes":["Built from pięć, but the spelling is piętnaście.",null,"The ś in -naście is missing.","Pięćdziesiąt is 50."]},{"id":"a1-vocabulary-numbers-days-months-q2","type":"multiple-choice","kind":"form","prompt":"How do you say 'on Saturday'?","options":["w sobota","w sobotę","na sobotę","w sobote"],"correct":1,"explanation":"'On' + a day is w + a changed ending: sobota → w sobotę.","optionNotes":["The ending must change: -a → -ę.",null,"Na sobotę means 'for Saturday'.","The ę needs its mark."]},{"id":"a1-vocabulary-numbers-days-months-q3","type":"multiple-choice","kind":"form","prompt":"Which day comes after czwartek (Thursday)?","options":["środa","piątek","wtorek","sobota"],"correct":1,"explanation":"poniedziałek, wtorek, środa, czwartek, piątek, sobota, niedziela.","optionNotes":["Środa is Wednesday, the day before czwartek.",null,"Wtorek is Tuesday.","Sobota is Saturday, two days after czwartek."]},{"id":"a1-vocabulary-numbers-days-months-q4","type":"multiple-choice","kind":"form","prompt":"42 = ?","options":["czterdzieści dwa","czterdzieści i dwa","czterdziesiąt dwa","cztery dwa"],"correct":0,"explanation":"Tens + units, with no 'and': czterdzieści dwa.","optionNotes":[null,"No 'and' inside a number.","-dziesiąt is for 50–90; 40 is czterdzieści.","That is just 'four two'."]}]};
